def mc_antithetic(f, n):
    # U와 1-U 쌍: 음의 상관으로 분산 감소
    total = 0.0
    for _ in range(n // 2):
        u = rand()
        total += (f(u) + f(1 - u)) / 2
    return total / (n // 2)

def mc_control(f, g, g_mean, n):
    # g: 기댓값 g_mean을 아는 통제변수
    xs = [rand() for _ in range(n)]
    fx = [f(x) for x in xs]
    gx = [g(x) for x in xs]
    mf, mg = sum(fx) / n, sum(gx) / n
    cov = sum((a - mf) * (b - mg) for a, b in zip(fx, gx))
    var = sum((b - mg) ** 2 for b in gx)
    c = cov / var  # 최적 계수 c* = Cov(f,g)/Var(g)
    return mf - c * (mg - g_mean)
